<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free PDF Metadata Viewer','description'=>'View basic PDF metadata such as size, version and page count.','url'=>'https://smarttoolz.in/tools/pdf-metadata-viewer/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>PDF Metadata Viewer</h1><p>Inspect basic PDF file information locally.</p></section><section class="tool-workspace"><div class="tool-panel"><input id="f" type="file" accept="application/pdf"><button id="go" class="tool-btn">Inspect PDF</button><pre id="o"></pre></div></section></main><script>go.onclick=async()=>{let f=document.getElementById('f').files[0];if(!f)return;let b=new Uint8Array(await f.arrayBuffer()),s=new TextDecoder('latin1').decode(b.slice(0,2000000)),pages=(s.match(/\/Type\s*\/Page\b/g)||[]).length;let m=s.match(/%PDF-([0-9.]+)/);o.textContent=`Name: ${f.name}\nSize: ${f.size.toLocaleString()} bytes\nPDF version: ${m?m[1]:'unknown'}\nEstimated pages: ${pages}`}</script><?php smarttoolz_tool_page_end(); ?>